import { CATERING_SERVICE_TYPES } from '@barakali/shared';
import manifest from './image-manifest.json';

export type CateringImageKey = (typeof CATERING_SERVICE_TYPES)[number]['imageKey'];

export interface ImageSource {
  src: string;
  srcSet: string;
  width: number;
  height: number;
}

// File names keep the requested width (800 / 1600); the manifest holds the real pixel size.
const REQUESTED_WIDTHS = [800, 1600] as const;

/** srcSet and intrinsic size for a catering photo generated by `pnpm catering:images`. */
export function imageSource(key: CateringImageKey): ImageSource {
  const variants = manifest[key];
  const files = REQUESTED_WIDTHS.map((requested, index) => ({
    url: `/catering/${key}-${requested}.webp`,
    width: variants[index]?.width ?? requested,
    height: variants[index]?.height ?? requested,
  }));
  const largest = files[files.length - 1] ?? files[0];
  return {
    src: files[0]?.url ?? '',
    srcSet: files.map((file) => `${file.url} ${file.width}w`).join(', '),
    width: largest?.width ?? 0,
    height: largest?.height ?? 0,
  };
}
